\label{def:internal-point}
We call a point $x\in K$ a \emph{D-internal point} of $K$ if for every $y\in K$ 
there is $\epsilon>0$ such that $x+\epsilon(x-y)\in K$.

Let $\mathbb{N}:=\{1,2,3,\dots\}$ and $\mathbb{N}_0:=\{0\}\cup\mathbb{N}$. 
The convex set $K$ is 
\begin{enumerate}
\item 
\emph{linearly compact} 
\cite{kendall62,klee63-compact} if $\ell\cap K$ is a compact line 
segment (possibly degenerated to a singleton) for every line 
$\ell$ in $V$ that meets $K$.

\item 
\emph{$k$-neighborly}\footnote{ 

The term \emph{$k$-neighborly} extends its homonym in the theory of 
polytopes \cite{gruenbaum03,sturmfels88,ziegler95}.}

if the convex hull of any $k$ or less extreme points of 
$K$ is a face of $K$, $k\in\mathbb{N}$.
\end{enumerate}

\label{pro:ext-fin}
Let 
\begin{align}
\label{eq:Hprime1}
H' & \textstyle 
:= \{ x\in H : 
\text{$x$ is a convex combination of at most $d+1$ extreme points}\\
\nonumber
& \textstyle \hspace{\widthof{$:=\{$}}
\text{$x_1,\dots,x_k$ of $K$ and $\alpha(x_1),\dots,\alpha(x_k)$ 
are affinely independent\,}\}.
\end{align}
\begin{enumerate}
\item
If $K$ is linearly compact then $\operatorname{ext} H\subset H'$.
\item 
If $K$ is $(d+1)$-neighborly and if $C$ is a singleton,
then $H'\subset\operatorname{ext} H$.
\end{enumerate}

\label{def:simplex}
The convex set $K$ is a \emph{simplex} 

\footnote{Simplices are called \emph{Choquet simplices} in \cite{winkler85}.}

if the convex cone 
\[
\{\lambda(x,1): \lambda\geq 0, x\in K\}\subset V\times\mathbb{R}
\] 
is a lattice in its own order \cite[Section~10]{phelps01}. A \emph{$k$-simplex}, $k\in\mathbb{N}_0$,
is defined as the convex hull of any $k+1$ affinely independent points.

\label{def:spec-Borel}
Let $\mu$ be a Borel measure on a topological space $X$. Then $\mu$ is a 
\emph{Radon measure} 

\footnote{Radon measures are also known as \emph{tight} measures \cite{topsoe70}.}

\cite{schwartz73} if $\mu$ is inner regular on compact sets, that is to say, the 
measure $\mu(A)$ of any $A\in\mathcal{B}(X)$ is the supremum of $\mu(B)$ over all compact 
subsets $B\subset A$. The measure $\mu$ is \emph{$\tau$-smooth} 

\footnote{It is well known that every Radon measure is $\tau$-smooth
\cite[Proposition~7.2.9]{bogachev07-vol2}. Also, for every $\tau$-smooth 
measure $\mu$ there exists a smallest closed set $A$ of full measure 
$\mu(A)=\mu(X)$, called the \emph{support} of $\mu$.}

if $\mu(\bigcup_{i\in I}A_i)=\sup_{i\in I}\mu(A_i)$ for every increasing net 
$(A_i)_{i\in I}$ of open sets \cite{topsoe70,winkler85}. Let $R$ and $P\!_\tau$
be the sets of Radon and $\tau$-smooth probability measures on $X$, respectively.

\label{def:moment-problems}
Building on Definition~\ref{def:moment-constraints}, we assume that $\mathbf{p}\colon X\to\mathbb{R}^d$ 
and $f\colon X\to(-\infty,+\infty]$ are measurable with respect to the $\sigma$-algebra 
$\mathcal{F}$. We define the linear optimization problems
\begin{align}
\label{eq:PM-atomic}
g_\mathrm{fin}(C) & \textstyle
:= \inf\{ \int f\mathrm{d}\mu : \mu\in G_\mathrm{fin}(C) \},\\

\label{eq:PM-aff-ind}
g_\mathrm{a.i.}(C) & \textstyle
:= \inf\{ \int f\mathrm{d}\mu : \mu\in G_\mathrm{a.i.}(C) \}
\end{align}
on the spaces $G_\mathrm{a.i.}(C)\subset G_\mathrm{fin}(C)$ of finitely atomic measures. If $f$ is 
bounded below by a real constant, then we also define
\begin{align}
\label{eq:PM}
g(C) & \textstyle
:= \inf\{ \int f\mathrm{d}\mu : \mu\in G(C) \},\\

\label{eq:PM-ext}
g_\mathrm{ext}(C) & \textstyle
:= \inf\{ \int f\mathrm{d}\mu : \mu\in \operatorname{ext} G(C) \}.
\end{align}
The optimization problem $g(\mathbf{q})$ in \eqref{eq:PM} at a specific point $\mathbf{q}\in\mathbb{R}^d$ 
is an example of the problem of moments \cite{shapiro01}. This problem is also known 
as the generalized moment problem if $\mathcal{F}=\mathcal{B}(X)$ is the Borel $\sigma$-algebra on a Borel 
\cite{lasserre10}, closed \cite{henrion-etal20}, or compact \cite{klerk-laurent19} set 
$X$ in $\mathbb{R}^k$. Loosely speaking, we refer to each of 
\eqref{eq:PM-atomic}--\eqref{eq:PM-ext} as a \emph{generalized moment problem}.

\label{exa:Silhavy}
Polyconvexity can be generalized to the so-called $\mathcal{A}$-polyconvexity. Roughly speaking, it is an analog of classical polyconvexity, but the gradients are replaced by a more general first-order differential operator $\mathcal{A}$, and we look at maps satisfying $\mathcal{A} u=0$. In fact, gradients can be described by $\mathcal{A}=\mathrm{curl}$, because $\mathrm{curl}\,\nabla $=0.  
The notion of $\mathcal{A}$-polyconvexity was used in \cite{silhavy18} where the author discusses variational problems in electromagnetism.

\label{cor:Dacorogna}
Let $P_1\subset Q$. If $\mathbf{p}$ and $f$ are measurable with respect to $\mathcal{F}$, and $f$ is bounded 
below by a real constant, then $g=g_\mathrm{fin}=g_\mathrm{a.i.}=g_\mathrm{ext}$ and $\operatorname{env}_\mathbf{p} f=g_\mathrm{fin}\circ\mathbf{p}$.
